 private void drawLibrary(){if(libraryList==null)return;libraryList.removeAllViews();libraryLabels.clear();libraryButtons.clear();previewButtons.clear();int count=0;String q=libraryQuery.trim().toLowerCase(Locale.ROOT);for(JSONObject t:AudioLibrary.tracks){String title=AudioLibrary.title(t);if(!libraryYear.equals("全部年份")&&!t.optString("date").startsWith(libraryYear))continue;if(onlyDownloaded&&!AudioLibrary.ready(t))continue;String hay=(title+" 六级 CET6 "+t.optString("date")+" "+t.optString("id")).toLowerCase(Locale.ROOT);boolean match=true;for(String word:q.split("\\s+"))if(!hay.contains(word))match=false;if(!match)continue;
   count++;LinearLayout c=column();c.setPadding(dp(16),dp(16),dp(16),dp(16));c.setBackground(shape(0xfffcfbf7,16));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.bottomMargin=dp(12);libraryList.addView(c,cp);c.addView(label(title,17,INK));gap(c,7);TextView state=label(AudioLibrary.state(t),12,MUTED);c.addView(state);libraryLabels.put(t.optString("id"),state);gap(c,12);LinearLayout actions=row(c);Button download=button("",()->libraryDownload(t));add(actions,download);libraryButtons.put(t.optString("id"),download);Button previewButton=button("试听",()->previewTrack(t));add(actions,previewButton);previewButtons.put(t.optString("id"),previewButton);add(actions,button("练习",()->practiceTrack(t)));c.setOnLongClickListener(v->{new AlertDialog.Builder(this).setTitle(title).setItems(new String[]{"删除下载及未完成文件"},(d,w)->new AlertDialog.Builder(this).setTitle("删除这套下载？").setMessage("当前练习录音和使用日志保留。").setNegativeButton("取消",null).setPositiveButton("删除",(a,b)->{try{stopPreview();AudioLibrary.remove(t);drawLibrary();}catch(Exception e){toast(e.getMessage());}}).show()).show();return true;});
  }if(count==0)libraryList.addView(label(onlyDownloaded?"没有符合条件的已下载音频":"没有符合条件的音频",14,MUTED));refreshLibrary();
 }
 private void refreshLibrary(){PlaybackService current=PlaybackService.instance;previewId=current!=null&&current.whole&&current.state!=null?current.state.optString("libraryId"):"";for(JSONObject t:AudioLibrary.tracks){String id=t.optString("id");TextView label=libraryLabels.get(id);if(label!=null)setText(label,AudioLibrary.state(t));Button pb=previewButtons.get(id);if(pb!=null){String text=id.equals(previewId)?"停止试听":"试听";if(!pb.getText().toString().equals(text))pb.setText(text);}Button b=libraryButtons.get(id);if(b!=null){String title=id.equals(LibraryService.activeId)?"暂停":AudioLibrary.ready(t)?"已下载":AudioLibrary.part(t).length()>0?"继续下载":"下载";if(!b.getText().toString().equals(title))b.setText(title);enabled(b,id.equals(LibraryService.activeId)||(!AudioLibrary.ready(t)&&LibraryService.activeId.isEmpty()));}}}
 private void libraryDownload(JSONObject t){String id=t.optString("id");if(id.equals(LibraryService.activeId)){LibraryService.cancel();return;}if(!LibraryService.activeId.isEmpty()){toast("请先暂停当前下载");return;}if(AudioLibrary.ready(t))return;Diagnostics.event("library_download_requested","id",id);startForegroundService(new Intent(this,LibraryService.class).putExtra("id",id));}
 private void stopPreview(){PlaybackService.stopCurrent();previewId="";}
 private void stopAll(){PlaybackService.stopCurrent();previewId="";}
 private void previewTrack(JSONObject t){String id=t.optString("id");PlaybackService current=PlaybackService.instance;if(current!=null&&current.state!=null&&id.equals(current.state.optString("libraryId"))&&current.whole){stopAll();return;}startForegroundService(new Intent(this,PlaybackService.class).setAction("preview").putExtra("id",id));previewId=id;}
 private void practiceTrack(JSONObject t){if(ProcessingService.busy){toast("请先暂停当前处理");return;}stopAll();long ticket=metadataTicket.incrementAndGet();repositoryLoading=true;switchTab(0);new Thread(()->{try{JSONObject state=Repository.load(t,()->ticket!=metadataTicket.get());runOnUiThread(()->{if(ticket==metadataTicket.get()){stopAll();Store.update(state);selected=0;repositoryLoading=false;rendered=-1;try{refreshState();}catch(Exception e){Diagnostics.error("repository_ui",e);}}});}catch(Exception e){runOnUiThread(()->{if(ticket==metadataTicket.get()){repositoryLoading=false;Diagnostics.error("repository_open",e);toast("资料加载失败，当前练习已保留；可联网重试");}});}},"repository-open").start();}
 private void refreshCatalogue(){toast("正在刷新");new Thread(()->{try{Repository.refresh();runOnUiThread(()->{if(tab==2){build();toast("目录已更新");}});}catch(Exception e){Diagnostics.error("repository_refresh",e);runOnUiThread(()->toast("刷新失败，已保留当前目录"));}},"repository-catalogue").start();}
