 private void fullText(){
  JSONObject state=Store.snapshot();JSONArray sentences=state.optJSONArray("sentences");if(sentences==null||sentences.length()==0)return;
  LinearLayout layout=column();layout.setPadding(dp(18),dp(12),dp(18),dp(12));LinearLayout controls=row(layout);
  final boolean[] follow={true},translations={showTranslation};final int[] highlighted={-1};
  Button back=button("回到当前句",()->follow[0]=true);add(controls,back);
  java.util.List<TextView> english=new ArrayList<>(),chinese=new ArrayList<>();
  Button toggle=button(showTranslation?"隐藏译文":"显示译文",null);toggle.setOnClickListener(v->{translations[0]=!translations[0];toggle.setText(translations[0]?"隐藏译文":"显示译文");for(TextView t:chinese)t.setVisibility(translations[0]?View.VISIBLE:View.GONE);});add(controls,toggle);
  ScrollView scroll=new ScrollView(this){@Override public boolean dispatchTouchEvent(android.view.MotionEvent event){if(event.getAction()==android.view.MotionEvent.ACTION_DOWN)follow[0]=false;return super.dispatchTouchEvent(event);}};LinearLayout text=column();scroll.addView(text);layout.addView(scroll,new LinearLayout.LayoutParams(-1,Math.max(dp(120),Math.min(dp(600),(int)(getResources().getDisplayMetrics().heightPixels*.6)))));
  try{for(int i=0;i<sentences.length();i++){final int index=i;JSONObject sentence=sentences.getJSONObject(i);TextView en=label(sentence.getString("text"),17,INK);en.setPadding(dp(8),dp(14),dp(8),dp(8));en.setOnClickListener(v->{selected=index;PlaybackService current=PlaybackService.instance;if(current!=null&&current.whole&&PlaybackService.matches(Store.snapshot()))PlaybackService.seek(this,sentence.optLong("startMs"),true);else playSelected();follow[0]=true;renderSelected();});text.addView(en);english.add(en);
   TextView zh=label(sentence.optString("translationScope").equals("paragraph")?"":sentence.optString("translation"),15,MUTED);zh.setPadding(dp(8),0,dp(8),dp(12));zh.setVisibility(translations[0]?View.VISIBLE:View.GONE);text.addView(zh);chinese.add(zh);
  }}catch(Exception e){Diagnostics.error("full_text",e);}
  AlertDialog dialog=new AlertDialog.Builder(this).setTitle("全文预览").setView(layout).setPositiveButton("关闭",null).create();
  Runnable sync=new Runnable(){public void run(){if(!dialog.isShowing())return;if(!activityVisible){handler.postDelayed(this,1500);return;}PlaybackService p=PlaybackService.instance;int index=p!=null&&PlaybackService.matches(currentState())?(p.whole?p.indexAt(p.position):p.sentence):selected;
   if(index>=0&&index<english.size()){if(index!=highlighted[0]){for(int i=0;i<english.size();i++){english.get(i).setTextColor(i==index?GREEN:INK);english.get(i).setBackground(i==index?shape(0xffe8ede6,10):null);}highlighted[0]=index;}int target=Math.min(english.get(index).getTop(),Math.max(0,text.getHeight()-scroll.getHeight()));if(follow[0]&&Math.abs(scroll.getScrollY()-target)>dp(40))scroll.smoothScrollTo(0,target);}handler.postDelayed(this,500);
  }};dialog.setOnDismissListener(d->handler.removeCallbacks(sync));dialog.show();handler.post(sync);
 }
 private void processingMode(){new AlertDialog.Builder(this).setTitle("处理模式").setSingleChoiceItems(new String[]{"低发热 · 1 线程，较长休息","均衡 · 最多 2 线程，间歇处理","快速 · 最多 4 线程"},ThermalGovernor.mode()==1?0:ThermalGovernor.mode()==4?2:1,(d,index)->{ThermalGovernor.mode(index==0?1:index==2?4:2);modeButton.setText("处理模式："+ThermalGovernor.modeName());d.dismiss();}).setNegativeButton("取消",null).show();}
 private void librarySource(){int sentences=0;for(JSONObject item:AudioLibrary.tracks)sentences+=item.optInt("sentences");TextView t=label("六级听力 · "+AudioLibrary.tracks.size()+" 套 · "+sentences+" 句\n\n资料仓库\nhappypotato2024 / buting-listening-resources\n\n录音与英文来源\nYsoseri1224 / CET-6-Listening-10-Years-Resources-and-Analysis\nCC BY 4.0\n\n本应用保留原始录音，制作逐句时间标记与单句参考译文。英文、译文和播放使用同一条句子记录；原段落对照另行保留。译文含 Google Translate 机器译文，非官方答案。\n\n资料覆盖以列表为准，不代表历年全部套卷。部分来源套号已按录音内容修正。",14,INK);t.setPadding(dp(20),dp(12),dp(20),dp(12));ScrollView s=new ScrollView(this);s.addView(t);new AlertDialog.Builder(this).setTitle("资料来源").setView(s).setNegativeButton("关闭",null).setNeutralButton("原始来源",(d,w)->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://github.com/Ysoseri1224/CET-6-Listening-10-Years-Resources-and-Analysis")))).setPositiveButton("资料仓库",(d,w)->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://github.com/"+Repository.REPO)))).show();}
