  LinearLayout actions=row(importCard);continueButton=button("继续处理",()->startTask("resume",null));cancelButton=button("暂停处理",ProcessingService::cancel);offlineButton=button("离线译文",()->startTask("offlineTranslate",null));add(actions,continueButton);add(actions,cancelButton);add(actions,offlineButton);
